import java.util.ArrayList;
import java.util.List;

// SMELL 1: God Class & Primitive Obsession & Leaked Encapsulation
class CustomerAccountManager {
    public String customerName;
    public String rawCardNumber; // Sensitive primitive unencrypted
    public double balance;
    private List<String> purchaseHistory = new ArrayList<>();

    // SMELL 2: Leaked mutable internal reference
    public List<String> getPurchaseHistory() {
        return purchaseHistory; // Callers can wipe out records!
    }

    // SMELL 3: Violates Single Responsibility (Charges + Emails + Logs)
    public void checkout(String item, double price) {
        // Feature Envy / Broken Invariants
        if (balance >= price) {
            balance -= price;
            purchaseHistory.add(item);
            System.out.println("Charged: $" + price);
            System.out.println("Sending SMTP Email to customer for " + item); // Direct IO coupling
        } else {
            System.out.println("Insufficient funds!");
        }
    }
}

public class CodeSmellAuditDemo {
    public static void main(String[] args) {
        CustomerAccountManager mgr = new CustomerAccountManager();
        mgr.customerName = "Alice";
        mgr.balance = 500.0;
        mgr.checkout("Keyboard", 100.0);

        // Exploit leaked reference:
        List<String> leaked = mgr.getPurchaseHistory();
        leaked.clear(); // Audit trail destroyed outside class control!
        System.out.println("History length after external tampering: " + mgr.getPurchaseHistory().size());
    }
}

