import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

// 1. Decoupled Notification Service
interface NotificationService {
    void notifyPurchase(String customer, String item);
}

class ConsoleNotifier implements NotificationService {
    @Override
    public void notifyPurchase(String customer, String item) {
        System.out.println("Notification dispatched to " + customer + " for " + item);
    }
}

// 2. Clean Domain Entity with Immutable Audit View
class SecureWallet {
    private final String owner;
    private double balance;
    private final List<String> transactions = new ArrayList<>();

    public SecureWallet(String owner, double initialBalance) {
        if (initialBalance < 0) throw new IllegalArgumentException("Negative balance disallowed");
        this.owner = owner;
        this.balance = initialBalance;
    }

    public boolean debit(double amount, String item) {
        if (amount <= 0 || amount > balance) return false;
        balance -= amount;
        transactions.add("Purchased: " + item + " for $" + amount);
        return true;
    }

    public double getBalance() { return balance; }
    public String getOwner() { return owner; }

    // Defensive unmodifiable view prevents external tampering
    public List<String> getTransactions() {
        return Collections.unmodifiableList(transactions);
    }
}

public class RefactoredAuditDemo {
    public static void main(String[] args) {
        SecureWallet wallet = new SecureWallet("Alice", 500.0);
        NotificationService notifier = new ConsoleNotifier();

        if (wallet.debit(100.0, "Mechanical Keyboard")) {
            notifier.notifyPurchase(wallet.getOwner(), "Mechanical Keyboard");
        }

        System.out.println("Remaining Balance: $" + wallet.getBalance());
        System.out.println("Logged Transactions: " + wallet.getTransactions().size());
    }
}

