class EmailAddress {
    private final String value;
    public EmailAddress(String value) {
        if (value == null || !value.contains("@")) {
            throw new IllegalArgumentException("Invalid email");
        }
        this.value = value;
    }
    public String getValue() { return value; }
}

class UserProfile {
    private final String username;
    private EmailAddress email;
    public UserProfile(String username, EmailAddress email) {
        if (username == null || email == null) throw new IllegalArgumentException("Null args");
        this.username = username;
        this.email = email;
    }
    public String getUsername() { return username; }
    public EmailAddress getEmail() { return email; }
    public void updateEmail(EmailAddress newEmail) {
        if (newEmail == null) throw new IllegalArgumentException("Null email");
        this.email = newEmail;
    }
}

public class ValueObjectDemo {
    public static void main(String[] args) {
        UserProfile profile = new UserProfile("munaf085", new EmailAddress("munaf@example.com"));
        System.out.println("User created: " + profile.getUsername() + " <" + profile.getEmail().getValue() + ">");
        try {
            new EmailAddress("bademail");
        } catch (IllegalArgumentException e) {
            System.out.println("Validation blocked invalid email");
        }
    }
}

class Order {
    private double subtotal;
    private int itemCount;

    public Order(double subtotal, int itemCount) {
        this.subtotal = subtotal;
        this.itemCount = itemCount;
    }

    // Tell, Don't Ask: calculation resides inside Order!
    public double calculateDiscountedTotal(double discountRate) {
        if (itemCount >= 5) {
            return subtotal * (1.0 - discountRate);
        }
        return subtotal;
    }
}

public class TellDontAskDemo {
    public static void main(String[] args) {
        Order order1 = new Order(200.0, 6);
        Order order2 = new Order(50.0, 2);
        System.out.println("Order 1 Final: $" + order1.calculateDiscountedTotal(0.20));
        System.out.println("Order 2 Final: $" + order2.calculateDiscountedTotal(0.20));
    }
}

