abstract class AccountBase {
    protected double balance;
    public AccountBase(double b) { this.balance = b; }
    public double getBalance() { return balance; }
    // BUG: Forcing deposit on all subclasses causes LSP violation!
    public abstract void deposit(double amount);
}

class StandardAccount extends AccountBase {
    public StandardAccount(double b) { super(b); }
    @Override
    public void deposit(double amount) { balance += amount; }
}

class ReadOnlyAccount extends AccountBase {
    public ReadOnlyAccount(double b) { super(b); }
    @Override
    public void deposit(double amount) {
        // LSP VIOLATION: Subclass rejects parent contract!
        throw new UnsupportedOperationException("Cannot deposit into read-only");
    }
}

public class LSPBugDemo {
    public static void main(String[] args) {
        AccountBase acc = new ReadOnlyAccount(100.0);
        acc.deposit(50.0); // Crashes with exception!
    }
}

