interface Account {
    double getBalance();
}

interface Depositable {
    void deposit(double amount);
}

class StandardAccount implements Account, Depositable {
    private double balance;
    public StandardAccount(double b) { this.balance = b; }
    @Override
    public double getBalance() { return balance; }
    @Override
    public void deposit(double amount) { balance += amount; }
}

class ReadOnlyAccount implements Account {
    private final double balance;
    public ReadOnlyAccount(double b) { this.balance = b; }
    @Override
    public double getBalance() { return balance; }
}

public class LSPBugDemo {
    public static void main(String[] args) {
        StandardAccount standard = new StandardAccount(100.0);
        standard.deposit(50.0);
        ReadOnlyAccount readOnly = new ReadOnlyAccount(200.0);

        System.out.println("Standard Balance: $" + standard.getBalance());
        System.out.println("ReadOnly Balance: $" + readOnly.getBalance());
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

class Sku {
    private final String code;
    public Sku(String code) {
        if (code == null || !code.startsWith("SKU-")) {
            throw new IllegalArgumentException("Invalid SKU format");
        }
        this.code = code;
    }
    public String getCode() { return code; }
}

class InventoryItem {
    private final Sku sku;
    private final String name;
    private int quantity;

    public InventoryItem(Sku sku, String name, int quantity) {
        this.sku = sku;
        this.name = name;
        this.quantity = Math.max(0, quantity);
    }

    public boolean reduceStock(int count) {
        if (count <= 0 || count > quantity) return false;
        quantity -= count;
        return true;
    }

    public Sku getSku() { return sku; }
    public String getName() { return name; }
    public int getQuantity() { return quantity; }
}

class Warehouse {
    private final List<InventoryItem> inventory = new ArrayList<>();
    public void addItem(InventoryItem item) { inventory.add(item); }
    public List<InventoryItem> getItems() {
        return Collections.unmodifiableList(inventory);
    }
}

public class InventoryRemediationApp {
    public static void main(String[] args) {
        Warehouse warehouse = new Warehouse();
        InventoryItem item = new InventoryItem(new Sku("SKU-MON-01"), "4K Monitor", 10);
        warehouse.addItem(item);

        boolean reduced = item.reduceStock(3);
        System.out.println("Reduced: " + reduced + ", remaining: " + item.getQuantity());
        System.out.println("Warehouse items: " + warehouse.getItems().size());
    }
}
